git diff -U0 -- design/gdd/emitter-state-and-light-exposure-query.md 2>/dev/null > /tmp/full.diff; python3 - <<'E' 2>&1 | head -c 60000
import re
t=open('/tmp/full.diff',encoding='utf-8').read().split('\n')
# print only word-level changes: for each -/+ pair show diff
import difflib
minus=[];plus=[];hdr=None
out=[]
def flush():
    global minus,plus
    for a,b in zip(minus,plus):
        sm=difflib.SequenceMatcher(None,a,b,autojunk=False)
        s=''
        for op,i1,i2,j1,j2 in sm.get_opcodes():
            if op=='equal':
                seg=a[i1:i2]
                s+= seg if len(seg)<80 else seg[:30]+' ... '+seg[-30:]
            else:
                if i2>i1: s+='[-'+a[i1:i2]+'-]'
                if j2>j1: s+='{+'+b[j1:j2]+'+}'
        out.append(hdr+'\n'+s)
    minus=[];plus=[]
for l in t:
    if l.startswith('@@'):
        flush();hdr=l[:30]
    elif l.startswith('-') and not l.startswith('---'): minus.append(l[1:])
    elif l.startswith('+') and not l.startswith('+++'): plus.append(l[1:])
flush()
print('\n\n'.join(out))
