git diff -U0 --word-diff=porcelain --word-diff-regex='[^[:space:]]+' -- design/gdd/emitter-state-and-light-exposure-query.md 2>/dev/null > /tmp/por.txt; cat > /tmp/p.js <<'E'
const fs=require('fs');const L=fs.readFileSync('/tmp/por.txt','utf8').split('\n');
let out=[],cur=null;
function ctxTrim(s){return s}
let buf='',hdr='';
for(const l of L){
 if(l.startsWith('@@')){ if(buf&&/[\[{]/.test(buf)) out.push(hdr+' '+buf.trim()); hdr=l.slice(0,22);buf='';continue}
 if(l.startsWith('diff')||l.startsWith('index')||l.startsWith('---')||l.startsWith('+++')||l.startsWith('warning'))continue;
 if(l==='~'){buf+='\n';continue}
 const c=l[0],t=l.slice(1);
 if(c===' '){ buf+= (t.length>0? ' '+(t):'') ; }
 else if(c==='-')buf+=' [-'+t+'-]'; else if(c==='+')buf+=' {+'+t+'+}';
}
if(buf)out.push(hdr+' '+buf.trim());
// compress unchanged runs
const res=out.map(o=>{
 const toks=o.split(' ');let r=[],run=[];
 const isch=t=>/^\[-|^\{\+|-\]$|\+\}$/.test(t);
 // simple: keep tokens within 6 of a change
 const keep=new Array(toks.length).fill(false);
 toks.forEach((t,i)=>{if(isch(t)||t.startsWith('[-')||t.startsWith('{+')){for(let j=Math.max(0,i-6);j<Math.min(toks.length,i+7);j++)keep[j]=true}});
 let s='',gap=false;toks.forEach((t,i)=>{if(keep[i]){s+=(gap?' ... ':' ')+t;gap=false}else gap=true});
 return s});
fs.writeFileSync('/tmp/out.txt',res.join('\n\n'));console.log(res.join('\n\n').length)
